impl DdParameterId {
    #[must_use]
    pub fn descriptor(self) -> &'static JclCatalogEntry<Self> {
        DD_PARAMETERS
            .iter()
            .find(|entry| entry.id == self)
            .expect("generated JCL identity is registered")
    }

    #[must_use]
    pub fn from_keyword(keyword: &str) -> Option<Self> {
        DD_PARAMETERS
            .iter()
            .find(|entry| {
                entry.keyword.eq_ignore_ascii_case(keyword)
                    || entry
                        .aliases
                        .iter()
                        .any(|alias| alias.eq_ignore_ascii_case(keyword))
            })
            .map(|entry| entry.id)
    }
}

